if ("test/integrations" in test or file_targets) and "test/api" not in test:
    test += " test/api/api_test.py::test_openapi"

# one test file has nothing to spread across workers
if len(file_targets) == 1:
    serial = True

runs_integrations = True
if scopes and not file_targets:
    runs_integrations = False
    for scope in scopes:
        if scope not in nonintegration_scopes:
            runs_integrations = True

if not serial:
    if num is None:
        if runs_integrations and os.environ.get("GITHUB_ACTIONS"):
            # an integration run waits on vendor responses rather than the cpu, so memory caps
            # throughput far above the core count. shorter runs just pay the import cost again
            num = 32
        else:
            num = "auto"
    if file_targets:
        # loadfile puts a whole file on one worker, so workers past the file count just idle
        cap = len(file_targets)
        num = cap if num == "auto" else min(int(num), cap)

# an integration file's tests share a connection and a fixed order, so the file stays on one
# worker. nothing else does, and pinning a big file to one worker leaves the rest idle
dist = "loadfile" if runs_integrations else "load"

# a serial run gets read in order, so name each test as it goes. xdist prefixes its own
test += " -v" if serial else f" --dist={dist} -n {num}"

run(test, "dev", True, False, False)

